1	using UnityEngine;
2	
3	public class GoalkeeperAI : MonoBehaviour
4	{
5	    [Header("Goalkeeper Settings")]
6	    [Tooltip("The ball GameObject to track")]
7	    public GameObject ball;
8	
9	    [Tooltip("Distance from goal when goalkeeper starts reacting")]
10	    public float reactionDistance = 11f;
11	
12	    [Tooltip("How good the goalkeeper is (0-1, higher = better saves)")]
13	    [Range(0f, 1f)]
14	    public float saveSkill = 0.7f;
15	
16	    [Header("Goal Dimensions")]
17	    [Tooltip("Goal width (left to right)")]
18	    public float goalWidth = 14f; // Expanded for goalkeeper reach
19	
20	    [Tooltip("Goal height")]
21	    public float goalHeight = 7f; // Standard soccer goal height
22	
23	    private Animator animator;
24	    private Rigidbody ballRigidbody;
25	    private bool isReacting = false;
26	    private Vector3 goalCenter;
27	    private Vector3 targetBallPosition;
28	    private bool shouldAdjustPosition = false;
29	    private Vector3 originalPosition;
30	    private Vector3 finalTargetPosition;
31	    private bool hasSetFinalTarget = false;
32	
33	    [Header("Hand Tracking")]
34	    [Tooltip("Transform representing the goalkeeper's left hand/glove")]
35	    public Transform leftHand;
36	    [Tooltip("Transform representing the goalkeeper's right hand/glove")]
37	    public Transform rightHand;
38	
39	    [Header("Ball Catching")]
40	    [Tooltip("Should the goalkeeper catch and hold the ball on successful saves?")]
41	    public bool enableBallCatching = true;
42	    [Tooltip("How strong the catch grip is (higher = ball sticks better)")]
43	    public float catchStrength = 500f;
44	
45	    private FixedJoint ballCatchJoint;
46	    private bool hasCaughtBall = false;
47	    private bool isResetting = false; // Prevent reset loops
48	    private float lastBallReleaseTime = -10f; // Track when ball was last released
49	    private float catchCooldown = 2f; // Minimum time before catching again after release
50	
51	    [Header("Dynamic Hand Positioning")]
52	    [Tooltip("Enable dynamic hand positioning during saves")]
53	    public bool enableDynamicHands = true;
54	    [Tooltip("How quickly hands adjust to ball position (0-1, higher = faster)")]
55	    [Range(0f, 1f)]
56	    public float handTrackingSpeed = 0.7f;
57	    [Tooltip("Maximum distance hands can move from their animation position")]
58	    public float maxHandAdjustment = 0.8f;
59	
60	    private Vector3 leftHandOriginalPos;
61	    private Vector3 rightHandOriginalPos;
62	    private bool isTrackingBallWithHands = false;
63	
64	    void Start()
65	    {
66	        animator = GetComponent<Animator>();
67	        goalCenter = transform.position; // Assume goalkeeper starts at goal center
68	        Debug.Log($"Goalkeeper positioned at goal center: {goalCenter}");
69	        if (ball != null)
70	        {
71	            ballRigidbody = ball.GetComponent<Rigidbody>();
72	        }
73	    }
74	
75	    void Update()
76	    {
77	        if (ball != null && ballRigidbody != null && !isReacting)
78	        {
79	            CheckForIncomingBall();
80	        }
81	
82	        // Dynamically adjust goalkeeper position during save animations
83	        if (shouldAdjustPosition && isReacting)
84	        {
85	            AdjustGoalkeeperPosition();
86	        }
87	
88	        // Keep ball between hands while caught
89	        if (hasCaughtBall && ball != null)
90	        {
91	            UpdateBallPositionBetweenHands();
92	        }
93	
94	        // Dynamic hand positioning during saves
95	        if (enableDynamicHands && isTrackingBallWithHands && isReacting && !hasCaughtBall)
96	        {
97	            UpdateDynamicHandPositioning();
98	        }
99	    }
100	
101	    void CheckForIncomingBall()
102	    {
103	        Vector3 ballPosition = ball.transform.position;
104	        Vector3 ballVelocity = ballRigidbody.linearVelocity;
105	
106	        // Check if ball is moving toward goal and close enough
107	        float distanceToGoal = Vector3.Distance(ballPosition, goalCenter);
108	        bool ballMovingTowardGoal = Vector3.Dot(ballVelocity.normalized, (goalCenter - ballPosition).normalized) > 0.5f;
109	
110	        if (distanceToGoal <= reactionDistance && ballMovingTowardGoal && ballVelocity.magnitude > 5f)
111	        {
112	            PredictBallTrajectory();
113	        }
114	    }
115	
116	    void PredictBallTrajectory()
117	    {
118	        Vector3 ballPosition = ball.transform.position;
119	        Vector3 ballVelocity = ballRigidbody.linearVelocity;
120	
121	        Debug.Log($"Ball velocity when goalkeeper reacts: {ballVelocity} (magnitude: {ballVelocity.magnitude:F2} m/s)");
122	
123	        // Calculate time to reach goal line
124	        float timeToGoal = Mathf.Abs((goalCenter.z - ballPosition.z) / ballVelocity.z);
125	
126	        // If ball is moving away from goal or time is too long, don't predict
127	        if (ballVelocity.z <= 0 || timeToGoal > 2f)
128	        {
129	            Debug.Log("Ball not heading toward goal or too slow - no save attempt");
130	            return;
131	        }
132	
133	        // Calculate apparent trajectory at moment of detection (for animation speed)
134	        // This is where the ball APPEARS to be heading based on current velocity
135	        float apparentX = ballPosition.x + (ballVelocity.x * timeToGoal) - goalCenter.x;
136	
137	        // Realistic trajectory prediction including gravity and drag
138	        Vector3 predictedPosition = PredictBallPositionAtTime(ballPosition, ballVelocity, timeToGoal);
139	
140	        // Sanity check: don't let prediction go too extreme
141	        predictedPosition.y = Mathf.Max(predictedPosition.y, -2f); // Don't predict too far underground
142	        predictedPosition.y = Mathf.Min(predictedPosition.y, 10f); // Don't predict too high
143	
144	        // Calculate where ball will actually cross goal line (for save type selection)
145	        float ballX = predictedPosition.x - goalCenter.x; // Relative to goal center
146	        float ballY = predictedPosition.y - goalCenter.y; // Height relative to goal center (can be negative for ground level)
147	        float ballSpeed = ballVelocity.magnitude;
148	
149	        Debug.Log($"Trajectory prediction: Time={timeToGoal:F2}s, Apparent X={apparentX:F2}, Final pos=({ballX:F2}, {ballY:F2}), Original Y={ballVelocity.y:F2}");
150	        Debug.Log($"Goal center Y: {goalCenter.y:F2}, Predicted ball Y: {predictedPosition.y:F2}, Ball height relative to goal: {ballY:F2}");
151	
152	        // Determine save type based on predicted position, but use apparent position for animation speed
153	        ChooseSaveAnimation(ballX, ballY, ballSpeed, apparentX);
154	    }
155	
156	    Vector3 PredictBallPositionAtTime(Vector3 startPos, Vector3 startVel, float time)
157	    {
158	        // Use lighter physics simulation that matches soccer ball behavior
159	        float gravityEffect = -9.81f; // Use realistic gravity
160	        float groundLevel = 0.11f; // Soccer ball radius (approximate ground level)
161	        float airDragCoeff = 0.02f; // Lighter air resistance
162	        float groundDragCoeff = 0.15f; // Ground friction when rolling
163	
164	        // Try to get actual values from BallController
165	        BallController ballController = ball.GetComponent<BallController>();
166	        if (ballController != null)
167	        {
168	            airDragCoeff = ballController.airDrag;
169	            groundDragCoeff = ballController.groundFriction;
170	        }
171	
172	        // Step-by-step simulation to handle ground collision properly
173	        Vector3 position = startPos;
174	        Vector3 velocity = startVel;
175	        float deltaTime = 0.02f; // 50fps simulation
176	        float elapsedTime = 0f;
177	        bool onGround = startPos.y <= groundLevel;
178	
179	        while (elapsedTime < time)
180	        {
181	            float dt = Mathf.Min(deltaTime, time - elapsedTime);
182	
183	            if (onGround)
184	            {
185	                // Ball is rolling on ground
186	                velocity.y = 0f; // No vertical movement
187	                position.y = groundLevel; // Keep on ground
188	
189	                // Apply ground friction
190	                Vector3 horizontalVel = new Vector3(velocity.x, 0f, velocity.z);
191	                float speed = horizontalVel.magnitude;
192	                if (speed > 0.01f)
193	                {
194	                    Vector3 dragForce = -horizontalVel.normalized * (groundDragCoeff * speed * dt);
195	                    velocity += dragForce;
196	                }
197	
198	                // Update horizontal position
199	                position.x += velocity.x * dt;
200	                position.z += velocity.z * dt;
201	            }
202	            else
203	            {
204	                // Ball is in air - apply gravity and air drag
205	                velocity.y += gravityEffect * dt;
206	
207	                // Apply air drag
208	                float speed = velocity.magnitude;
209	                if (speed > 0.01f)
210	                {
211	                    Vector3 dragForce = -velocity.normalized * (airDragCoeff * speed * dt);
212	                    velocity += dragForce;
213	                }
214	
215	                // Update position
216	                position += velocity * dt;
217	
218	                // Check for ground collision
219	                if (position.y <= groundLevel)
220	                {
221	                    position.y = groundLevel;
222	                    velocity.y = -velocity.y * 0.3f; // Bounce with energy loss
223	                    onGround = velocity.y > -1f; // Stay on ground if bounce is small
224	                }
225	            }
226	
227	            elapsedTime += dt;
228	        }
229	
230	        return position;
231	    }
