233	    void ChooseSaveAnimation(float ballX, float ballY, float ballSpeed, float apparentX)
234	    {
235	        isReacting = true;
236	
237	        // Set animator parameters
238	        animator.SetFloat("BallDirection", ballX);
239	        animator.SetFloat("BallHeight", ballY);
240	        animator.SetFloat("BallSpeed", ballSpeed);
241	
242	        // Determine save type based on ball position
243	        int saveType = 0; // 0 = Idle
244	
245	        // Check if goalkeeper should attempt save (based on skill and ball position)
246	        bool shouldAttemptSave = ShouldAttemptSave(ballX, ballY, ballSpeed);
247	
248	        if (shouldAttemptSave)
249	        {
250	            bool isLeftSide = ballX < 0; // Ball coming to goalkeeper's left
251	            float absX = Mathf.Abs(ballX);
252	
253	            Debug.Log($"Save type decision: ballX={ballX:F2}, ballY={ballY:F2}, absX={absX:F2}, isLeftSide={isLeftSide}");
254	
255	            // Categorize shot height more accurately
256	            if (ballY > 3.5f)
257	            {
258	                // Very high shots - jumping saves
259	                if (absX >= 1f) // Side high shots
260	                {
261	                    saveType = isLeftSide ? 7 : 8; // High diving saves
262	                }
263	                else // Central high shots
264	                {
265	                    saveType = 4; // Central high save
266	                }
267	            }
268	            else if (ballY < 1.2f)
269	            {
270	                // Low shots - ground level or just above
271	                if (absX > 2f) // Very wide low shots
272	                {
273	                    saveType = isLeftSide ? 9 : 10; // Wide diving saves
274	                }
275	                else if (absX >= 0.7f) // Side low shots
276	                {
277	                    saveType = isLeftSide ? 5 : 6; // Side low saves
278	                }
279	                else // Central low shots
280	                {
281	                    if (ballY <= 0.3f) // Ground level
282	                    {
283	                        saveType = 1; // Ground scoop
284	                    }
285	                    else if (ballY <= 0.7f)// Low but not ground
286	                    {
287	                        saveType = 2; // Low catch
288	                    }
289	                    else
290	                    {
291	                        saveType = 3; // Central catch
292	                    }
293	                }
294	            }
295	            else
296	            {
297	                // Mid-height shots (1.2f to 3.5f)
298	                if (absX > 2.5f) // Very wide mid shots
299	                {
300	                    saveType = isLeftSide ? 7 : 8; // High diving saves for wide shots
301	                }
302	                else if (absX >= 1.0f) // Wide shots - definitely need full diving
303	                {
304	                    // Ball is far enough that goalkeeper must dive/jump to reach it
305	                    saveType = isLeftSide ? 9 : 10; // Low diving saves - jump and reach
306	                }
307	                else if (absX >= 0.6f) // Moderate side shots - body block range
308	                {
309	                    // Shots close enough for body block - drop to side and extend arms
310	                    saveType = isLeftSide ? 5 : 6; // Body block/side saves (drop and extend)
311	                }
312	                else // Central mid shots
313	                {
314	                    saveType = 3; // Central catch
315	                }
316	            }
317	        }
318	        else
319	        {
320	            // Goalkeeper misses or reacts too late
321	            saveType = 11; // Miss animation
322	        }
323	
324	        string saveTypeDescription = saveType switch
325	        {
326	            3 => "Central catch",
327	            5 => "Left body block (drop and extend)",
328	            6 => "Right body block (drop and extend)",
329	            9 => "Left diving save (jump and reach)",
330	            10 => "Right diving save (jump and reach)",
331	            _ => $"SaveType {saveType}"
332	        };
333	
334	        Debug.Log($"Save decision: ballX={ballX:F2}, ballY={ballY:F2}, absX={Mathf.Abs(ballX):F2} -> {saveTypeDescription}");
335	
336	        // Set save type parameter
337	        animator.SetInteger("SaveType", saveType);
338	
339	        // Store target position for dynamic adjustment during animation
340	        targetBallPosition = new Vector3(ballX + goalCenter.x, ballY + goalCenter.y, goalCenter.z);
341	        originalPosition = transform.position;
342	
343	        // Start dynamic hand tracking for realistic hand positioning
344	        if (enableDynamicHands && saveType != 11) // Don't track hands during miss animations
345	        {
346	            StartDynamicHandTracking();
347	        }
348	
349	        // Only enable adjustment for ground scoop shots near center (the problematic case)
350	        shouldAdjustPosition = false;
351	        if (saveType == 1 && Mathf.Abs(ballX) < 0.8f) // Only for ground scoops close to center
352	        {
353	            // Will enable adjustment after animation starts
354	        }
355	
356	        // Calculate animation speed based on ball speed and APPARENT shot width (not final curved position)
357	        float animationSpeed = CalculateAnimationSpeed(ballSpeed, Mathf.Abs(apparentX));
358	        animator.SetFloat("AnimationSpeed", animationSpeed);
359	
360	        // Calculate optimal save timing based on ball speed and distance
361	        float timeToGoal = CalculateTimeToGoal();
362	        float saveDelay = CalculateOptimalSaveDelay(timeToGoal, ballSpeed, Mathf.Abs(ballX));
363	
364	        Debug.Log($"Ball timing: {timeToGoal:F2}s to goal, Save delay: {saveDelay:F2}s, Animation speed: {animationSpeed:F2}x");
365	
366	        // Trigger the animation after calculated delay
367	        if (saveDelay > 0f)
368	        {
369	            Invoke(nameof(TriggerSave), saveDelay);
370	        }
371	        else
372	        {
373	            TriggerSave(); // Immediate save for very fast shots
374	        }
375	
376	        Debug.Log($"Ball predicted at X:{ballX:F2}, Y:{ballY:F2}, Speed:{ballSpeed:F2} - SaveType: {saveType}, ApparentX:{apparentX:F2}, AnimSpeed:{animationSpeed:F2}");
377	    }
378	
379	    bool ShouldAttemptSave(float ballX, float ballY, float ballSpeed)
380	    {
381	        // Check if ball is within goal bounds (including goalkeeper reach)
382	        float goalkeeperReach = 2f; // Extra reach beyond goal posts
383	        bool withinReachWidth = Mathf.Abs(ballX) <= (goalWidth / 2f + goalkeeperReach);
384	        bool withinReachHeight = ballY >= -1f && ballY <= (goalHeight + 2f); // More generous height range
385	
386	        Debug.Log($"Ball final position: X={ballX:F2}, Y={ballY:F2} | Goal bounds: W={goalWidth / 2f:F1}, H={goalHeight:F1} | Within reach: Width={withinReachWidth}, Height={withinReachHeight}");
387	
388	        if (!withinReachWidth || !withinReachHeight)
389	        {
390	            Debug.Log("Ball out of goalkeeper reach - no save attempt");
391	            return false;
392	        }
393	
394	        // For shots within reach, always attempt save (simplify for now)
395	        Debug.Log("Ball within goalkeeper reach - attempting save!");
396	        return true;
397	
398	        // TODO: Re-enable difficulty calculation later if needed
399	        // Calculate save difficulty based on distance and speed
400	        // float saveDistance = Mathf.Sqrt(ballX * ballX + Mathf.Max(0f, ballY - 1f) * Mathf.Max(0f, ballY - 1f));
401	        // float speedFactor = Mathf.Clamp01(ballSpeed / 25f);
402	        // float saveDifficulty = (saveDistance / 4f) + (speedFactor * 0.3f);
403	        // float saveChance = saveSkill - saveDifficulty;
404	        // return saveChance > 0.1f;
405	    }
406	
407	    float CalculateTimeToGoal()
408	    {
409	        Vector3 ballPosition = ball.transform.position;
410	        Vector3 ballVelocity = ballRigidbody.linearVelocity;
411	
412	        // Calculate time for ball to reach goalkeeper's z-position
413	        float distanceToGoalkeeper = Mathf.Abs(ballPosition.z - goalCenter.z);
414	        float timeToGoal = distanceToGoalkeeper / Mathf.Max(0.1f, ballVelocity.z); // Prevent division by zero
415	
416	        return timeToGoal;
417	    }
418	
419	    float CalculateOptimalSaveDelay(float timeToGoal, float ballSpeed, float ballDistance)
420	    {
421	        // Base timing: faster shots need quicker reactions, slower shots can wait
422	        float speedFactor = Mathf.Clamp01(ballSpeed / 20f); // Normalize to 0-1 (20 m/s = max)
423	
424	        // Distance factor: wider shots need earlier dives
425	        float distanceFactor = Mathf.Clamp01(ballDistance / 3f); // Normalize distance
426	
427	        // Calculate delay: slower/closer shots can wait longer
428	        float baseDelay = timeToGoal * 0.6f; // Start save at 60% of flight time
429	        float speedAdjustment = speedFactor * -0.3f; // Faster shots: react earlier (-0.3s)
430	        float distanceAdjustment = distanceFactor * -0.2f; // Wider shots: react earlier (-0.2s)
431	
432	        float optimalDelay = baseDelay + speedAdjustment + distanceAdjustment;
433	
434	        // Clamp to reasonable bounds
435	        optimalDelay = Mathf.Clamp(optimalDelay, 0f, 1.5f); // Max 1.5 second delay
436	
437	        return optimalDelay;
438	    }
439	
440	    float CalculateAnimationSpeed(float ballSpeed, float shotWidth)
441	    {
442	        // Base animation speed based on ball speed
443	        float baseSpeed;
444	
445	        if (ballSpeed >= 20f)
446	        {
447	            // Very fast shots: speed up animations significantly but keep realistic
448	            // 20+ m/s → 1.3x to 1.6x speed
449	            float speedRatio = Mathf.Clamp(ballSpeed / 25f, 0.8f, 1f); // 20-25 m/s range
450	            baseSpeed = 1.3f + (speedRatio * 0.3f); // 1.3x to 1.6x
451	        }
452	        else if (ballSpeed >= 15f)
453	        {
454	            // Fast shots: moderate speed increase
455	            // 15-20 m/s → 1.1x to 1.3x speed
456	            float speedRatio = (ballSpeed - 15f) / 5f; // 0 to 1 for 15-20 m/s
457	            baseSpeed = 1.1f + (speedRatio * 0.2f); // 1.1x to 1.3x
458	        }
459	        else if (ballSpeed >= 10f)
460	        {
461	            // Normal shots: standard speed with slight variation
462	            // 10-15 m/s → 0.9x to 1.1x speed
463	            float speedRatio = (ballSpeed - 10f) / 5f; // 0 to 1 for 10-15 m/s
464	            baseSpeed = 0.9f + (speedRatio * 0.2f); // 0.9x to 1.1x
465	        }
466	        else
467	        {
468	            // Slow shots: can use slightly slower, more deliberate animations
469	            // <10 m/s → 0.8x to 0.9x speed
470	            baseSpeed = 0.8f + (ballSpeed / 10f * 0.1f); // 0.8x to 0.9x
471	        }
472	
473	        // Width factor: wider shots need faster animations to cover more distance
474	        float widthFactor = 1f;
475	
476	        if (shotWidth > 3f)
477	        {
478	            // Very wide shots (near posts): significant speed increase
479	            // 3+ units → +30% to +50% speed bonus
480	            float wideRatio = Mathf.Clamp01((shotWidth - 3f) / 4f); // 0-1 for 3-7 unit range
481	            widthFactor = 1.3f + (wideRatio * 0.2f); // 1.3x to 1.5x multiplier
482	        }
483	        else if (shotWidth > 1.5f)
484	        {
485	            // Moderately wide shots: moderate speed increase
486	            // 1.5-3 units → +10% to +30% speed bonus
487	            float wideRatio = (shotWidth - 1.5f) / 1.5f; // 0-1 for 1.5-3 unit range
488	            widthFactor = 1.1f + (wideRatio * 0.2f); // 1.1x to 1.3x multiplier
489	        }
490	        else if (shotWidth > 0.5f)
491	        {
492	            // Slightly wide shots: small speed increase
493	            // 0.5-1.5 units → +0% to +10% speed bonus
494	            float wideRatio = (shotWidth - 0.5f) / 1f; // 0-1 for 0.5-1.5 unit range
495	            widthFactor = 1f + (wideRatio * 0.1f); // 1.0x to 1.1x multiplier
496	        }
497	        // Central shots (0-0.5 units): no width bonus (widthFactor = 1.0f)
498	
499	        float finalSpeed = baseSpeed * widthFactor;
500	
501	        // Cap maximum animation speed to keep it realistic
502	        finalSpeed = Mathf.Min(finalSpeed, 2.2f); // Max 2.2x speed
503	
504	        return finalSpeed;
505	    }
506	
507	    void TriggerSave()
508	    {
509	        animator.SetTrigger("ShouldSave");
510	
511	        // Check if this is a ground scoop that needs adjustment
512	        int currentSaveType = animator.GetInteger("SaveType");
513	        if (currentSaveType == 1 && Mathf.Abs(targetBallPosition.x - goalCenter.x) < 0.8f)
514	        {
515	            Debug.Log($"Ground scoop detected! Ball at X={targetBallPosition.x:F2}, Center at X={goalCenter.x:F2}");
516	            // Only adjust for ground scoops near center
517	            Invoke(nameof(StartPositionAdjustment), 0.15f); // Slightly longer delay
518	        }
519	    }
520	
521	    void StartPositionAdjustment()
522	    {
523	        shouldAdjustPosition = true; // Enable dynamic tracking
524	        Debug.Log("Starting dynamic hand-ball alignment system");
525	    }
526	
527	    void AdjustGoalkeeperPosition()
528	    {
529	        // Calculate target position only once if not set, then move smoothly toward it
530	        if (!hasSetFinalTarget)
531	        {
532	            // Calculate where the ball will be and where the hands currently are
533	            Vector3 currentBallPos = ball.transform.position;
534	            Vector3 ballVelocity = ballRigidbody.linearVelocity;
535	
536	            // Predict ball position at goal line
537	            float timeToGoal = Mathf.Abs((goalCenter.z - currentBallPos.z) / Mathf.Max(0.1f, ballVelocity.z));
538	            Vector3 predictedBallPos = PredictBallPositionAtTime(currentBallPos, ballVelocity, timeToGoal);
539	
540	            // Get current hand positions (use the lower hand for ground shots)
541	            Vector3 handPosition = Vector3.zero;
542	            if (leftHand != null && rightHand != null)
543	            {
544	                // For ground scoops, use whichever hand is lower/closer to ground
545	                handPosition = (leftHand.position.y < rightHand.position.y) ? leftHand.position : rightHand.position;
546	            }
547	            else if (leftHand != null)
548	            {
549	                handPosition = leftHand.position;
550	            }
551	            else if (rightHand != null)
552	            {
553	                handPosition = rightHand.position;
554	            }
555	            else
556	            {
557	                // Fallback: estimate hand position relative to goalkeeper body
558	                handPosition = transform.position + Vector3.down * 0.5f;
559	            }
560	
561	            // Calculate how much to move the goalkeeper so his hand aligns with ball
562	            float handToBallOffset = predictedBallPos.x - handPosition.x;
563	
564	            // Limit adjustment to reasonable range
565	            handToBallOffset = Mathf.Clamp(handToBallOffset, -0.4f, 0.4f);
566	
567	            // Set final target position - ONLY adjust X, keep Y and Z from original position
568	            Vector3 initialPos = transform.position;
569	            finalTargetPosition = new Vector3(initialPos.x + handToBallOffset, originalPosition.y, originalPosition.z);
570	            hasSetFinalTarget = true;
571	
572	            Debug.Log($"Calculated adjustment: HandX={handPosition.x:F3}, BallX={predictedBallPos.x:F3}, Offset={handToBallOffset:F3}");
573	        }
574	
575	        // Smooth movement toward the fixed target position - ONLY on X axis
576	        Vector3 currentPos = transform.position;
577	        float adjustmentSpeed = 1.5f; // Smooth, controlled speed
578	
579	        // Calculate new X position, but keep current Y and Z
580	        float newX = Mathf.MoveTowards(currentPos.x, finalTargetPosition.x, adjustmentSpeed * Time.deltaTime);
581	        Vector3 newPosition = new Vector3(newX, currentPos.y, currentPos.z);
582	
583	        // Apply the position adjustment
584	        transform.position = newPosition;
585	
586	        // Stop adjusting when close enough or ball is very close
587	        float distanceToBall = Vector3.Distance(ball.transform.position, goalCenter);
