681	    void HandleBallCollision(Collision collision)
682	    {
683	        Rigidbody ballRb = collision.rigidbody;
684	        if (ballRb != null)
685	        {
686	            // Get the collision point and normal
687	            Vector3 collisionPoint = collision.contacts[0].point;
688	            Vector3 collisionNormal = collision.contacts[0].normal;
689	
690	            // Reduce ball speed on contact (goalkeeper catches/deflects)
691	            Vector3 currentVelocity = ballRb.linearVelocity;
692	            float impactSpeed = Vector3.Dot(currentVelocity, -collisionNormal);
693	
694	            Debug.Log($"Ball collision: Point={collisionPoint}, IsReacting={isReacting}, ImpactSpeed={impactSpeed:F2}");
695	
696	            // Apply deflection based on goalkeeper skill and collision
697	            if (isReacting && impactSpeed > 0)
698	            {
699	                // Successful save - goalkeeper is actively trying to save
700	                // Check if it's a good save position - either close to hands OR torso/stomach area
701	                bool canCatch = false;
702	                string catchReason = "";
703	
704	                // Check distance to hands first (primary catch condition)
705	                float distanceToHands = GetDistanceToClosestHand(collisionPoint);
706	                Debug.Log($"Distance to closest hand: {distanceToHands:F2}");
707	
708	                if (distanceToHands < 0.8f) // Close to hands
709	                {
710	                    canCatch = true;
711	                    catchReason = $"close to hands (distance: {distanceToHands:F2})";
712	                }
713	                else
714	                {
715	                    // Check distance to goalkeeper center/torso (secondary catch condition)
716	                    Vector3 goalkeeperCenter = transform.position + Vector3.up * 1f; // Approximate chest height
717	                    float distanceFromCenter = Vector3.Distance(collisionPoint, goalkeeperCenter);
718	                    Debug.Log($"Distance to goalkeeper center: {distanceFromCenter:F2}");
719	
720	                    if (distanceFromCenter < 0.7f) // Close to torso/stomach
721	                    {
722	                        canCatch = true;
723	                        catchReason = $"close to torso (distance: {distanceFromCenter:F2})";
724	                    }
725	                }
726	
727	                // Check catch cooldown to prevent infinite catch-release loops
728	                bool withinCatchCooldown = Time.time - lastBallReleaseTime < catchCooldown;
729	
730	                if (canCatch && enableBallCatching && !hasCaughtBall && !withinCatchCooldown)
731	                {
732	                    // Excellent save - try to catch the ball
733	                    AttemptBallCatch(ballRb, collisionPoint);
734	                }
735	                else if (withinCatchCooldown)
736	                {
737	                    // Catch blocked - within cooldown period
738	                }
739	                else
740	                {
741	                    // Decent save - significant speed reduction but no catch
742	                    ballRb.linearVelocity = currentVelocity * 0.1f; // Keep only 10%
743	                }
744	            }
745	            else
746	            {
747	                // Glancing blow or goalkeeper not actively saving
748	                // Still reduce speed more than before for realism
749	                Vector3 deflection = collisionNormal * impactSpeed * 0.3f;
750	                ballRb.linearVelocity = currentVelocity * 0.7f + deflection; // Reduce to 70% + slight deflection
751	            }
752	        }
753	    }
