759	        // Position ball between both hands for realistic catching
760	        Vector3 catchPosition = GetBetweenHandsPosition();
761	
762	        if (catchPosition != Vector3.zero)
763	        {
764	            // Stop the ball's movement immediately
765	            ballRb.linearVelocity = Vector3.zero;
766	            ballRb.angularVelocity = Vector3.zero;
767	            ballRb.isKinematic = true; // Make ball kinematic so it doesn't fall
768	
769	            // Position ball between hands for realistic catching pose
770	            ball.transform.position = catchPosition;
771	            ball.transform.parent = transform; // Parent to goalkeeper body, not individual hand
772	
773	            hasCaughtBall = true;
774	
775	            // Stop dynamic hand tracking since ball is now caught
776	            StopDynamicHandTracking();
777	
778	            // Set animator to IdleBall animation (will transition from current state)
779	            if (animator != null)
780	            {
781	                animator.SetBool("HasBall", true); // Triggers transition from ANY state to IdleBall
782	            }
783	
784	            // Release the ball after a few seconds
785	            Invoke(nameof(ReleaseBall), 3f);
786	        }
787	        else
788	        {
789	            // Fallback: position at goalkeeper chest
790	            ballRb.linearVelocity = Vector3.zero;
791	            ballRb.angularVelocity = Vector3.zero;
792	            ballRb.isKinematic = true;
793	
794	            ball.transform.position = transform.position + Vector3.up * 1.2f + Vector3.forward * 0.3f; // Chest level
795	            ball.transform.parent = transform;
796	
797	            hasCaughtBall = true;
798	
799	            // Stop dynamic hand tracking since ball is now caught
800	            StopDynamicHandTracking();
801	
802	            // Set animator to IdleBall animation for fallback catch too
803	            if (animator != null)
804	            {
805	                animator.SetBool("HasBall", true);
806	            }
