812	    float GetDistanceToClosestHand(Vector3 collisionPoint)
813	    {
814	        if (leftHand == null && rightHand == null) return float.MaxValue; // No hands available
815	        if (leftHand == null) return Vector3.Distance(rightHand.position, collisionPoint);
816	        if (rightHand == null) return Vector3.Distance(leftHand.position, collisionPoint);
817	
818	        // Return distance to whichever hand is closer
819	        float leftDistance = Vector3.Distance(leftHand.position, collisionPoint);
820	        float rightDistance = Vector3.Distance(rightHand.position, collisionPoint);
821	
822	        return Mathf.Min(leftDistance, rightDistance);
823	    }
824	
825	    Vector3 GetBetweenHandsPosition()
826	    {
827	        if (leftHand != null && rightHand != null)
828	        {
829	            // Position ball exactly between both hands
830	            Vector3 midpoint = (leftHand.position + rightHand.position) / 2f;
831	            // Slightly forward from hands for better visual
832	            Vector3 forward = transform.forward * 0.15f;
833	            return midpoint + forward;
834	        }
835	        else if (leftHand != null)
836	        {
837	            // Only left hand available
838	            return leftHand.position + transform.forward * 0.2f;
839	        }
840	        else if (rightHand != null)
841	        {
842	            // Only right hand available  
843	            return rightHand.position + transform.forward * 0.2f;
844	        }
845	
846	        return Vector3.zero; // No hands available
847	    }
848	
849	    Transform GetClosestHand(Vector3 collisionPoint)
850	    {
851	        if (leftHand == null && rightHand == null) return null;
852	        if (leftHand == null) return rightHand;
853	        if (rightHand == null) return leftHand;
854	
855	        // Return whichever hand is closer to the collision point
856	        float leftDistance = Vector3.Distance(leftHand.position, collisionPoint);
857	        float rightDistance = Vector3.Distance(rightHand.position, collisionPoint);
858	
859	        return (leftDistance < rightDistance) ? leftHand : rightHand;
860	    }
