862	    void UpdateBallPositionBetweenHands()
863	    {
864	        if (ball == null || !hasCaughtBall) return;
865	
866	        // Get current position between hands
867	        Vector3 targetPosition = GetBetweenHandsPosition();
868	
869	        if (targetPosition != Vector3.zero)
870	        {
871	            // Smoothly move ball to position between hands
872	            ball.transform.position = Vector3.Lerp(ball.transform.position, targetPosition, Time.deltaTime * 15f);
873	
874	            // Optional: Add slight rotation for more natural look
