879	    void ReleaseBall()
880	    {
881	        if (hasCaughtBall && ball != null)
882	        {
883	            Debug.Log("Releasing caught ball");
884	
885	            // Unparent the ball
886	            ball.transform.parent = null;
887	
888	            // Restore physics
889	            if (ballRigidbody != null)
890	            {
891	                ballRigidbody.isKinematic = false;
892	                // Give the ball more velocity to move it away from goalkeeper hands
893	                Vector3 awayFromGoalkeeper = (ball.transform.position - transform.position).normalized;
894	                ballRigidbody.linearVelocity = Vector3.down * 3f + awayFromGoalkeeper * 2f; // Drop and push away
895	            }
896	
897	            // Clean up joint if it exists
898	            if (ballCatchJoint != null)
899	            {
900	                Destroy(ballCatchJoint);
901	                ballCatchJoint = null;
902	            }
903	
904	            hasCaughtBall = false;
905	            lastBallReleaseTime = Time.time; // Record when ball was released
906	
907	            // Set animator back to normal Idle animation
908	            if (animator != null)
909	            {
910	                animator.SetBool("HasBall", false); // Return to normal Idle animation
911	            }
912	
913	            // Note: No need to trigger reset - 8-second timer will handle it automatically
914	        }
915	    }
