929	    void UpdateDynamicHandPositioning()
930	    {
931	        if (leftHand == null || rightHand == null || ball == null) return;
932	
933	        // Predict where ball will be in the next 0.3 seconds (reaction time)
934	        Vector3 ballPosition = ball.transform.position;
935	        Vector3 ballVelocity = ballRigidbody.linearVelocity;
936	        Vector3 predictedBallPos = PredictBallPositionAtTime(ballPosition, ballVelocity, 0.3f);
937	
938	        // Convert predicted position to local goalkeeper space
939	        Vector3 localPredictedPos = transform.InverseTransformPoint(predictedBallPos);
940	
941	        // Only adjust hands if ball is coming toward the goalkeeper's body area
942	        if (localPredictedPos.z > -1.5f && localPredictedPos.z < 1f) // Ball is close to goalkeeper
943	        {
944	            AdjustHandTowardsBall(leftHand, leftHandOriginalPos, localPredictedPos, true);
945	            AdjustHandTowardsBall(rightHand, rightHandOriginalPos, localPredictedPos, false);
946	        }
947	    }
948	
949	    void AdjustHandTowardsBall(Transform hand, Vector3 originalLocalPos, Vector3 localBallPos, bool isLeftHand)
950	    {
951	        // Calculate desired hand position based on ball location
952	        Vector3 desiredLocalPos = originalLocalPos;
953	
954	        // Adjust Y position based on ball height - more aggressive for body-level shots
955	        if (localBallPos.y < 0.5f) // Ball is very low (hip/stomach level)
956	        {
957	            desiredLocalPos.y = Mathf.Max(localBallPos.y - 0.1f, originalLocalPos.y - maxHandAdjustment);
958	        }
959	        else if (localBallPos.y < 1.2f) // Ball is at torso/chest level
960	        {
961	            desiredLocalPos.y = Mathf.Max(localBallPos.y - 0.2f, originalLocalPos.y - maxHandAdjustment);
962	        }
963	        else if (localBallPos.y > 2f) // Ball is high
964	        {
965	            desiredLocalPos.y = Mathf.Min(localBallPos.y + 0.2f, originalLocalPos.y + maxHandAdjustment);
966	        }
967	
968	        // Adjust X position - hands move toward ball's X position for body shots
969	        float ballX = localBallPos.x;
970	        float ballXAbs = Mathf.Abs(ballX);
971	
972	        // More aggressive hand movement for shots coming directly at goalkeeper's body
973	        if (ballXAbs < 0.7f) // Ball is coming at center/body area
974	        {
975	            if (isLeftHand && ballX < 0.2f) // Left hand moves toward center-left balls
976	            {
977	                desiredLocalPos.x = Mathf.Max(ballX + 0.2f, originalLocalPos.x - maxHandAdjustment);
978	            }
979	            else if (!isLeftHand && ballX > -0.2f) // Right hand moves toward center-right balls
980	            {
981	                desiredLocalPos.x = Mathf.Min(ballX - 0.2f, originalLocalPos.x + maxHandAdjustment);
982	            }
983	        }
984	
985	        // Smoothly interpolate to desired position
986	        Vector3 currentLocalPos = transform.InverseTransformPoint(hand.position);
987	        Vector3 newLocalPos = Vector3.Lerp(currentLocalPos, desiredLocalPos, handTrackingSpeed * Time.deltaTime * 6f);
988	        hand.position = transform.TransformPoint(newLocalPos);
989	    }
990	
991	    void StartDynamicHandTracking()
992	    {
993	        if (leftHand != null && rightHand != null)
994	        {
995	            // Store original hand positions relative to goalkeeper
996	            leftHandOriginalPos = transform.InverseTransformPoint(leftHand.position);
997	            rightHandOriginalPos = transform.InverseTransformPoint(rightHand.position);
998	            isTrackingBallWithHands = true;
999	        }
1000	    }
1001	
1002	    void StopDynamicHandTracking()
1003	    {
1004	        isTrackingBallWithHands = false;
1005	    }
1006	}

