81	    // External concurrent queue filled by your network listener
82	    public ConcurrentQueue<HitData> hitQueue;
83	
84	    void Awake()
85	    {
86	        rb = GetComponent<Rigidbody>();
87	        if (hitQueue == null)
88	            hitQueue = new ConcurrentQueue<HitData>();
89	    }
90	
91	    void FixedUpdate()
92	    {
93	        // Store velocity for bounce detection
94	        lastVelocity = rb.linearVelocity;
95	
96	        // 1) Apply any queued hits (instant changes coming from simulator)
97	        while (hitQueue != null && hitQueue.TryDequeue(out HitData hit))
98	        {
99	            ApplyHit(hit);
100	        }
101	
102	        // 2) Check for bounces
103	        CheckForBounce();
104	
105	        // 3) Apply physics decay (air resistance, ground friction, spin decay)
106	        ApplyPhysicsDecay();
107	
108	        // 4) Apply Magnus effect each physics step (if there is spin AND velocity)
109	        ApplyMagnus();
110	
111	        // 5) Apply visual rotation (cosmetic only)
112	        ApplyVisualRotation();
113	
114	        // 6) Check for auto-reset if ball has been stationary too long
115	        CheckAutoReset();
116	    }
117	
118	    void ApplyHit(HitData hit)
119	    {
120	        // direction
121	        Vector3 dir = Vector3.forward;
122	        if (hit.dir != null && hit.dir.Length >= 3)
123	            dir = new Vector3(hit.dir[0], hit.dir[1], hit.dir[2]);
124	
125	        if (dir.sqrMagnitude < 1e-6f)
126	        {
127	            dir = Vector3.forward; // Use world forward instead of transform.forward
128	        }
129	        dir.Normalize();
130	
131	        // speed mapping: real tracked shots carry an actual m/s value (speedMps > 0)
132	        // from the middleware; simulated/manual hits (SimulatedHitSender) only set
133	        // speed_norm, so fall back to the normalized*maxSpeed mapping for those.
134	        float speed = hit.speedMps > 0f ? hit.speedMps : Mathf.Clamp01(hit.speed_norm) * maxSpeed;
135	
136	        // either overwrite velocity (best for deterministic simulator input)
137	        if (overwriteVelocity)
138	        {
139	            rb.linearVelocity = dir * speed;
140	        }
141	        else
142	        {
143	            Vector3 impulse = dir * speed * rb.mass;
144	            rb.AddForce(impulse, ForceMode.Impulse);
145	        }
146	
147	        // Store spin data for Magnus effect (but don't apply as angular velocity)
148	        Vector3 spinVec = Vector3.zero;
149	        if (hit.spin != null && hit.spin.Length == 3)
150	            spinVec = new Vector3(hit.spin[0], hit.spin[1], hit.spin[2]);
151	
152	        // Store the spin for Magnus effect calculation
153	        currentSpin = spinVec;
154	
155	        // Mark that ball has been hit (for auto-reset tracking)
156	        hasBeenHit = true;
157	        timeSinceHit = 0f; // Reset timer since hit
158	        resetTriggered = false; // Reset flag for new shot
159	
160	        // DON'T apply spin as angular velocity - this was causing the circular motion
161	        // We'll use the spin data in the Magnus effect calculation instead
162	
163	        // Optional: latency compensation by moving ball forward along velocity (requires synced timestamps)
164	        // if (hit.timestamp > 0) { ... }
165	    }
166	
167	    void ApplyMagnus()
168	    {
169	        // Use stored spin data instead of angular velocity for Magnus effect
170	        Vector3 omega = currentSpin; // Use the spin from the hit data
171	        Vector3 v = rb.linearVelocity;
172	
173	        if (omega.sqrMagnitude > 1e-6f && v.sqrMagnitude > 1e-6f)
174	        {
175	            // Magnus force: F_magnus = magnusFactor * (omega x v)
176	            // For Y-axis spin (curve left/right): omega.y creates force in X direction
177	            Vector3 magnus = Vector3.Cross(omega, v) * magnusFactor;
178	            rb.AddForce(magnus, magnusForceMode);
179	        }
180	    }
181	
182	    void ApplyPhysicsDecay()
183	    {
184	        // Check if ball is on ground or in air
185	        bool onGround = IsOnGround();
186	
187	        // Apply velocity decay
188	        Vector3 currentVelocity = rb.linearVelocity;
189	        float currentSpeed = currentVelocity.magnitude;
190	
191	        // Don't apply physics if ball is kinematic (being held by goalkeeper)
192	        if (!rb.isKinematic)
193	        {
194	            if (currentSpeed > minVelocityThreshold)
195	            {
196	                // Simple velocity decay - much more predictable
197	                float decayRate = onGround ? groundFriction : airDrag;
198	                Vector3 newVelocity = currentVelocity * (1f - decayRate * Time.fixedDeltaTime);
199	                rb.linearVelocity = newVelocity;
200	            }
201	            else
202	            {
203	                // Stop the ball if velocity is below threshold
204	                rb.linearVelocity = Vector3.zero;
205	            }
206	        }
207	
208	        // Apply spin decay over time
209	        if (currentSpin.sqrMagnitude > 1e-6f)
210	        {
211	            float decayRate = onGround ? spinDecay * 2f : spinDecay; // Spin decays faster on ground
212	            currentSpin = Vector3.Lerp(currentSpin, Vector3.zero, decayRate * Time.fixedDeltaTime);
213	
214	            // Stop spin if it's very low
215	            if (currentSpin.sqrMagnitude < 0.01f)
216	            {
217	                currentSpin = Vector3.zero;
218	            }
219	        }
220	    }
221	
222	    bool IsOnGround()
223	    {
224	        // Cast a ray downward to check if ball is close to ground
225	        RaycastHit hit;
226	        Vector3 rayStart = transform.position;
227	        Vector3 rayDirection = Vector3.down;
228	
229	        // Use the ball's collider radius if available, otherwise use groundCheckDistance
230	        float rayDistance = groundCheckDistance;
231	        Collider ballCollider = GetComponent<Collider>();
232	        if (ballCollider is SphereCollider sphereCol)
233	        {
234	            rayDistance = sphereCol.radius + groundCheckDistance;
235	        }
236	
237	        bool isGrounded = Physics.Raycast(rayStart, rayDirection, out hit, rayDistance);
238	
239	        // Optional: Draw debug ray in Scene view
240	        Debug.DrawRay(rayStart, rayDirection * rayDistance, isGrounded ? Color.green : Color.red);
241	
242	        return isGrounded;
243	    }
244	
245	    void CheckForBounce()
246	    {
247	        bool currentlyGrounded = IsOnGround();
248	
249	        // Detect bounce: was airborne, now grounded, and has significant downward velocity
250	        if (wasAirborne && currentlyGrounded && lastVelocity.y < -minBounceVelocity)
251	        {
252	            ApplyBounce();
253	        }
254	
255	        // Update airborne state for next frame
256	        wasAirborne = !currentlyGrounded;
257	    }
258	
259	    void ApplyBounce()
260	    {
261	        Vector3 velocity = rb.linearVelocity;
262	
263	        // Separate horizontal and vertical components
264	        Vector3 horizontalVelocity = new Vector3(velocity.x, 0f, velocity.z);
265	        float verticalVelocity = velocity.y;
266	
267	        // Apply bounce to vertical component (reverse and reduce)
268	        float newVerticalVelocity = -verticalVelocity * bounceCoefficient;
269	
270	        // Apply damping to horizontal component (surface friction)
271	        Vector3 newHorizontalVelocity = horizontalVelocity * horizontalDamping;
272	
273	        // Combine and apply new velocity
274	        Vector3 newVelocity = new Vector3(newHorizontalVelocity.x, newVerticalVelocity, newHorizontalVelocity.z);
275	        rb.linearVelocity = newVelocity;
276	
277	        // Apply spin effects from bounce
278	        if (currentSpin.sqrMagnitude > 1e-6f)
279	        {
280	            // Reduce spin magnitude
281	            currentSpin *= spinBounceEffect;
282	
283	            // Backspin can add to bounce height, topspin reduces it
284	            if (currentSpin.x != 0) // X-axis spin affects bounce
285	            {
286	                float spinEffect = currentSpin.x * 0.5f; // Backspin = positive X
287	                rb.linearVelocity = new Vector3(newVelocity.x, newVelocity.y + spinEffect, newVelocity.z);
288	            }
289	        }
290	    }
291	
292	    void ApplyVisualRotation()
293	    {
294	        Vector3 velocity = rb.linearVelocity;
295	        bool onGround = IsOnGround();
296	
297	        // Calculate visual rotation based on ball movement and spin
298	        Vector3 rotationThisFrame = Vector3.zero;
299	
300	        if (onGround && velocity.sqrMagnitude > 0.1f)
301	        {
302	            // Ball is rolling on ground - calculate rotation based on movement
303	            float ballRadius = 0.11f; // Standard soccer ball radius in meters
304	            Collider ballCollider = GetComponent<Collider>();
305	            if (ballCollider is SphereCollider sphereCol)
306	            {
307	                ballRadius = sphereCol.radius * transform.localScale.x; // Account for scale
308	            }
309	
310	            // Rolling rotation: distance / radius = angle in radians
311	            Vector3 horizontalVelocity = new Vector3(velocity.x, 0f, velocity.z);
312	            float rollSpeed = horizontalVelocity.magnitude;
313	            float rollAngle = (rollSpeed * Time.fixedDeltaTime) / ballRadius * Mathf.Rad2Deg;
314	
315	            // Roll around X-axis for forward/backward movement, Z-axis for left/right
316	            Vector3 rollAxis = Vector3.Cross(Vector3.up, horizontalVelocity.normalized);
317	            rotationThisFrame += rollAxis * rollAngle * visualRollMultiplier;
318	        }
319	
320	        // Add spin-based rotation (works both in air and on ground)
321	        if (currentSpin.sqrMagnitude > 1e-6f)
322	        {
323	            // Convert spin (rad/s) to degrees/frame
324	            Vector3 spinRotation = currentSpin * Mathf.Rad2Deg * Time.fixedDeltaTime * visualSpinMultiplier;
325	            rotationThisFrame += spinRotation;
326	        }
327	
328	        // Apply the rotation to the transform
329	        if (rotationThisFrame.sqrMagnitude > 1e-6f)
330	        {
331	            transform.Rotate(rotationThisFrame, Space.World);
332	        }
333	    }
334	
335	    void CheckAutoReset()
336	    {
337	        // Only check for auto-reset if the feature is enabled and ball has been hit
338	        if (autoResetTime <= 0f)
339	        {
340	            return;
341	        }
342	
343	        if (!hasBeenHit)
344	        {
345	            return;
346	        }
347	
348	        // Always increment timer after ball has been hit, regardless of movement
349	        timeSinceHit += Time.fixedDeltaTime;
350	
351	        // If enough time has passed since hit, trigger reset (only once)
352	        if (timeSinceHit >= autoResetTime && !resetTriggered)
353	        {
354	            resetTriggered = true; // Mark reset as triggered to prevent multiple calls
355	            TriggerAutoReset();
356	        }
357	    }
358	
359	    void TriggerAutoReset()
360	    {
361	        if (goalDetector != null)
362	        {
363	            goalDetector.ManualReset();
364	        }
365	        else
366	        {
367	            // Fallback: just reset ball position if no GoalDetector reference
368	            transform.position = Vector3.zero;
369	            rb.linearVelocity = Vector3.zero;
370	            rb.angularVelocity = Vector3.zero;
371	            currentSpin = Vector3.zero;
372	        }
373	
374	        // Reset tracking variables
375	        hasBeenHit = false;
376	        timeSinceHit = 0f;
377	    }
378	
379	    // Public method to reset the auto-reset timer (called when ball is manually reset)
380	    public void ResetAutoResetTimer()
381	    {
382	        hasBeenHit = false;
383	        timeSinceHit = 0f;
384	        resetTriggered = false; // Reset flag for next shot
385	    }
386	}
