388	// Serializable container for JSON mapping
389	[System.Serializable]
390	public class HitData
391	{
392	    public double timestamp;   // optional (seconds); you can ignore if you don't use timestamps
393	    public float[] dir;        // length 3
394	    public float speed_norm;   // 0..1, used only when speedMps <= 0
395	    public float[] spin;       // optional length 3 (rad/s suggested)
396	    public float speedMps;     // real m/s speed from the middleware; overrides speed_norm when > 0
397	}
